BEGIN;
CREATE TABLE IF NOT EXISTS assurance_certificate (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, project_id uuid NOT NULL, goal_id uuid NOT NULL, revision_set_id text NOT NULL, profile_version text NOT NULL, issuer_identity text NOT NULL, scope jsonb NOT NULL, claims jsonb NOT NULL, evidence_root text NOT NULL, signature jsonb NOT NULL, valid_from timestamptz NOT NULL, valid_until timestamptz NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS certificate_status_event (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, project_id uuid NOT NULL, goal_id uuid NOT NULL, revision_set_id text NOT NULL, certificate_id uuid NOT NULL, event_type text NOT NULL, reason text, event_hash text NOT NULL, occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recognition_decision (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, project_id uuid NOT NULL, goal_id uuid NOT NULL, revision_set_id text NOT NULL, certificate_id uuid NOT NULL, relying_party text NOT NULL, arrangement_profile text NOT NULL, scope_match jsonb NOT NULL, jurisdiction jsonb NOT NULL, decision text NOT NULL, limitations jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sector_assurance_profile (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, project_id uuid NOT NULL, goal_id uuid NOT NULL, revision_set_id text NOT NULL, sector text NOT NULL, product_classification jsonb NOT NULL, applicable_standards jsonb NOT NULL, tailored_controls jsonb NOT NULL, external_review jsonb, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE assurance_certificate ENABLE ROW LEVEL SECURITY; ALTER TABLE certificate_status_event ENABLE ROW LEVEL SECURITY; ALTER TABLE recognition_decision ENABLE ROW LEVEL SECURITY; ALTER TABLE sector_assurance_profile ENABLE ROW LEVEL SECURITY;
COMMIT;
